<?php

declare(strict_types=1);

namespace App\Features\Backup\Domain\Entities;

use App\Features\Shared\Domain\BaseEntity;
use DateTimeImmutable;
use InvalidArgumentException;

use function base64_decode;
use function strlen;

/**
 * One row of `backup_encryption_keys` (database.md:550-565): the
 * AES-256 key used for `ZipArchive::setEncryptionName()` per-entry
 * encryption of backup archives. The raw key is a 44-character base64
 * encoding of 32 random bytes (the format generated by
 * `backup:generate-key` and required by the DR upload form,
 * backup.md:461,591).
 *
 * The entity holds the **raw** key value — encryption at rest
 * (`Crypt`, under APP_KEY) is an Infra persistence concern; the
 * repository encrypts on write and decrypts on read (backup.md:495).
 * Exactly one key is active at a time; the invariant is enforced by
 * the generation use case (database.md:563), not by the entity.
 */
final class EncryptionKey extends BaseEntity
{
    public const RAW_KEY_LENGTH = 44;

    public const MAX_NAME_LENGTH = 100;

    public function __construct(
        private readonly int $id,
        private readonly string $name,
        private readonly string $keyValue,
        private bool $isActive,
        private readonly DateTimeImmutable $createdAt,
        private readonly DateTimeImmutable $updatedAt,
    ) {
        $this->validateName($name);
        $this->validateKeyValue($keyValue);
    }

    /**
     * Materializes a stored `backup_encryption_keys` row (array keys
     * match the column names: id, name, key_value, is_active,
     * created_at, updated_at). `key_value` is the **decrypted** raw
     * key — the repository decrypts the ciphertext column before
     * materialization.
     *
     * @param  array<string, mixed>  $row
     */
    public static function fromRow(array $row): self
    {
        return new self(
            id: (int) $row['id'],
            name: (string) $row['name'],
            keyValue: (string) $row['key_value'],
            isActive: (bool) $row['is_active'],
            createdAt: new DateTimeImmutable($row['created_at']),
            updatedAt: new DateTimeImmutable($row['updated_at']),
        );
    }

    public function toId(): int
    {
        return $this->id;
    }

    public function toName(): string
    {
        return $this->name;
    }

    /**
     * The raw key value — displayed exactly once at generation time
     * (backup.md:498); the workflow passes it to the archive's
     * encryption/decryption.
     */
    public function toKeyValue(): string
    {
        return $this->keyValue;
    }

    public function isActive(): bool
    {
        return $this->isActive;
    }

    public function toCreatedAt(): DateTimeImmutable
    {
        return $this->createdAt;
    }

    public function toUpdatedAt(): DateTimeImmutable
    {
        return $this->updatedAt;
    }

    public function activate(): void
    {
        $this->isActive = true;
    }

    public function deactivate(): void
    {
        $this->isActive = false;
    }

    private function validateName(string $name): void
    {
        if ($name === '' || strlen($name) > self::MAX_NAME_LENGTH) {
            throw new InvalidArgumentException(
                sprintf('Encryption key name must be a non-empty string of at most %d characters.', self::MAX_NAME_LENGTH),
            );
        }
    }

    private function validateKeyValue(string $keyValue): void
    {
        $decoded = base64_decode($keyValue, true);

        if (strlen($keyValue) !== self::RAW_KEY_LENGTH || $decoded === false || strlen($decoded) !== 32) {
            throw new InvalidArgumentException(
                'Encryption key value must be a 44-character base64 encoding of 32 random bytes.',
            );
        }
    }
}
